// Build a workspace's Page.tsx with the component library, screenshot it and run
// the program checks. The generator agent runs this after every edit.
//
//   node scripts/shoot.mjs <workspace>
//
// <workspace> holds Page.tsx and data.json. Writes into it:
//   shot.png       the page, 1248px wide (the 1152px frame with a 48px margin)
//   thumb.png      the same at half width (what the judge sees as the overview)
//   tile-N.png     640px slices with 64px overlap (what the judge sees as detail)
//   checks.json    program check results
// Prints the check results; exit code 0 even when checks fail (they are findings).
import fs from "node:fs"
import path from "node:path"
import http from "node:http"
import { build } from "vite"
import react from "@vitejs/plugin-react"
import tailwindcss from "@tailwindcss/vite"
import { chromium } from "playwright-core"
import { createRequire } from "node:module"

const require = createRequire(import.meta.url)

const ws = path.resolve(process.argv[2] ?? ".")
// The component library: the shared one, or a candidate the component agent is working on in <ws>/app.
const APP = fs.existsSync(path.join(ws, "app", "index.html")) ? path.join(ws, "app") : path.resolve(import.meta.dirname, "..", "app")
const OUT = path.join(ws, ".build")
const VIEWPORT = { width: 1440, height: 900 }
const CLIP_X = (VIEWPORT.width - 1152) / 2 - 48
const CLIP_W = 1152 + 96
const TILE_H = 640
const TILE_OVERLAP = 64

const findings = []
const add = (check, msg, line) => findings.push({ check, msg, ...(line && { line }) })

// ---------- source checks on Page.tsx, with line numbers ----------
const src = fs.readFileSync(path.join(ws, "Page.tsx"), "utf8")
const ALLOWED_IMPORT = /^(react|@\/components\/report|@\/components\/ui\/(table|progress|separator|item|chart)|\.\/data\.json)$/
const COLOR = /\b(?:text|bg|border|fill|stroke|from|to|via)-(?:red|green|blue|slate|gray|zinc|neutral|stone|orange|amber|yellow|lime|emerald|teal|cyan|sky|indigo|violet|purple|fuchsia|pink|rose|white|black)\b/
src.split("\n").forEach((line, i) => {
  const n = i + 1
  for (const m of line.matchAll(/from\s+["']([^"']+)["']/g))
    if (!ALLOWED_IMPORT.test(m[1])) add("组件库", `import 了组件库以外的模块 ${m[1]}`, n)
  if (/\bstyle=\{/.test(line)) add("统一刻度", "写了 inline style;尺寸、颜色只能来自组件和规范里的类名", n)
  for (const m of line.matchAll(/\b[\w:-]+-\[[^\]]+\]/g)) add("统一刻度", `任意值类名 ${m[0]}`, n)
  const c = line.match(COLOR)
  if (c) add("统一刻度", `直接写了颜色类名 ${c[0]};颜色只能来自组件(下降、严重用组件的 direction、tone)`, n)
  for (const m of line.matchAll(/\btext-(xs|sm|base|lg|xl|3xl|4xl|5xl|6xl|7xl|8xl|9xl)\b/g)) add("统一刻度", `字号类名 ${m[0]} 不在规范里(只允许结论句的 text-2xl)`, n)
  for (const m of line.matchAll(/<(h[1-6]|p|span|table|ul|ol|li|img|svg|button)\b/g)) add("组件库", `直接写了 <${m[1]}>,应使用组件库组件`, n)
  // The same tags through createElement / jsx() are the same thing written another way.
  for (const m of line.matchAll(/\b(?:createElement|jsxs?)\(\s*["'`]([a-z][a-z0-9]*)["'`]/g)) if (m[1] !== "div") add("组件库", `用 createElement 直接画了 <${m[1]}>,应使用组件库组件`, n)
})

// ---------- build ----------
fs.rmSync(OUT, { recursive: true, force: true })
try {
  await build({
    root: APP,
    base: "./",
    logLevel: "error",
    configFile: false,
    plugins: [
      // Tailwind emits only the classes it finds; point it at the workspace too.
      { name: "workspace-source", enforce: "pre", transform: (code, id) => (id.endsWith("/src/index.css") ? `${code}\n@source "${ws}/Page.tsx";\n` : null) },
      react(),
      tailwindcss(),
    ],
    // The workspace may sit outside this package, so React resolves from here.
    resolve: {
      alias: [
        { find: "@page", replacement: path.join(ws, "Page.tsx") },
        { find: /^react\/jsx-runtime$/, replacement: require.resolve("react/jsx-runtime") },
        { find: /^react\/jsx-dev-runtime$/, replacement: require.resolve("react/jsx-dev-runtime") },
        { find: /^react$/, replacement: require.resolve("react") },
        { find: "@", replacement: path.join(APP, "src") },
      ],
    },
    build: { outDir: OUT, emptyOutDir: true, chunkSizeWarningLimit: 8000 },
  })
  // The data's images (assets/<file>), served next to the page so components can show them.
  if (fs.existsSync(path.join(ws, "assets"))) fs.cpSync(path.join(ws, "assets"), path.join(OUT, "assets"), { recursive: true })
} catch (e) {
  add("能渲染", `构建失败:${String(e.message ?? e).split("\n").slice(0, 6).join(" ")}`)
  finish()
  process.exit(0)
}

// ---------- render ----------
const MIME = { ".png": "image/png", ".jpg": "image/jpeg", ".svg": "image/svg+xml", ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".json": "application/json", ".woff2": "font/woff2", ".woff": "font/woff" }
const server = http.createServer((req, res) => {
  const p = path.join(OUT, decodeURIComponent(new URL(req.url, "http://x").pathname))
  if (!p.startsWith(OUT) || !fs.existsSync(p) || fs.statSync(p).isDirectory()) return res.writeHead(404).end()
  res.writeHead(200, { "content-type": MIME[path.extname(p)] ?? "application/octet-stream" })
  fs.createReadStream(p).pipe(res)
})
await new Promise((r) => server.listen(0, "127.0.0.1", r))
const url = `http://127.0.0.1:${server.address().port}/index.html`
const browser = await chromium.launch({ executablePath: process.env.CHROMIUM_PATH ?? "/opt/pw-browsers/chromium" })

try {

try {
  const page = await browser.newPage({ viewport: VIEWPORT, deviceScaleFactor: 1 })
  const errors = []
  page.on("pageerror", (e) => errors.push(String(e)))
  await page.goto(url)
  await page.waitForFunction(() => window.__READY__ === true, null, { timeout: 30000 })
  for (const e of errors) add("能渲染", `页面报错:${e.slice(0, 200)}`)

  const dom = await page.evaluate(() => {
    // Images, canvases and the like that no library component drew: the page made them itself,
    // however the code spells it (<img>, createElement, a variable holding "img", new Image()...).
    const raw = [...document.querySelectorAll("img,canvas,video,iframe,picture,object,embed")].filter((e) => !e.hasAttribute("data-slot")).map((e) => e.tagName.toLowerCase())
    const images = [...document.images].map((i) => i.getAttribute("src") ?? "")
    const main = document.querySelector("main")
    if (!main) return { height: document.body.scrollHeight, text: document.body.innerText, images, out: [], unknown: 0, raw }
    const mr = main.getBoundingClientRect()
    const out = []
    // Inside a container that scrolls or hides horizontally (a strip of screenshots), what lies
    // past the edge is clipped on purpose; the container itself is still checked.
    const clipped = (el) => {
      for (let p = el.parentElement; p && p !== main; p = p.parentElement) if (getComputedStyle(p).overflowX !== "visible") return true
      return false
    }
    for (const el of main.querySelectorAll("*")) {
      const r = el.getBoundingClientRect()
      if (!r.width || !r.height || clipped(el)) continue
      if (r.left < mr.left - 1 || r.right > mr.right + 1) {
        const t = (el.innerText || el.textContent || "").trim().slice(0, 30)
        out.push(`${el.tagName.toLowerCase()}[${el.getAttribute("data-slot") ?? ""}] 超出页面左右边界 ${Math.round(Math.max(mr.left - r.left, r.right - mr.right))}px「${t}」`)
      }
    }
    return { height: Math.ceil(document.documentElement.scrollHeight), text: document.body.innerText, images, out: out.slice(0, 10), unknown: document.querySelectorAll("[data-slot=unknown]").length, raw }
  })
  if (dom.unknown) add("组件库", `${dom.unknown} 个组件类型未知`)
  if (dom.raw.length) {
    const n = dom.raw.reduce((m, t) => ({ ...m, [t]: (m[t] ?? 0) + 1 }), {})
    add("组件库", `页面上有不是组件库画的元素:${Object.entries(n).map(([t, k]) => `${k} 个 <${t}>`).join("、")};组件库没有的能力不要自己画,在最后的说明里写出缺什么组件`)
  }
  for (const o of dom.out) add("元素越界", o)

  // Data coverage: every short value outside long series should appear on the page.
  // A component demo has no data.json (the agent makes its own test data): nothing to compare.
  const data = fs.existsSync(path.join(ws, "data.json")) ? JSON.parse(fs.readFileSync(path.join(ws, "data.json"), "utf8")) : {}
  const text = dom.text.replace(/\s+/g, "")
  const missing = [], missingImages = []
  // Long series (more than 8 items) are only checked for their images.
  const walk = (v, p, imagesOnly = false) => {
    if (Array.isArray(v)) return v.forEach((x, i) => walk(x, `${p}/${i}`, imagesOnly || v.length > 8))
    if (v && typeof v === "object") return Object.entries(v).forEach(([k, x]) => walk(x, `${p}/${k}`, imagesOnly))
    if (typeof v === "boolean" || v == null) return
    if (/\/(key|direction|significant|id)$/.test(p)) return
    // An image counts when the page shows it: an <img> with the same file name (the build may add a hash).
    if (typeof v === "string" && /\.(png|jpe?g|webp|svg)$/i.test(v)) {
      const stem = path.basename(v).replace(/\.\w+$/, "")
      if (!dom.images.some((src) => path.basename(src.split("?")[0]).startsWith(stem))) missingImages.push(v)
      return
    }
    if (imagesOnly) return
    const s = String(v).replace(/\s+/g, "")
    const alts = typeof v === "number" ? [s, v.toLocaleString("en-US"), v.toFixed(1)] : [s]
    if (!alts.some((a) => text.includes(a))) missing.push(`${p}「${String(v).slice(0, 24)}」`)
  }
  walk(data, "")
  if (missingImages.length) add("数据忠实", `页面上没有显示 ${missingImages.length} 张图:${missingImages.slice(0, 6).join("、")}${missingImages.length > 6 ? " 等" : ""}`)
  if (missing.length) add("数据忠实", `页面上找不到 ${missing.length} 项数据:${missing.slice(0, 12).join("、")}${missing.length > 12 ? " 等" : ""}`)

  const clip = { x: CLIP_X, y: 0, width: CLIP_W, height: dom.height }
  await page.screenshot({ path: path.join(ws, "shot.png"), clip, fullPage: true })
  for (const f of fs.readdirSync(ws)) if (/^tile-\d+\.png$/.test(f)) fs.rmSync(path.join(ws, f))
  const tiles = []
  for (let y = 0; y < dom.height; y += TILE_H - TILE_OVERLAP) {
    const h = Math.min(TILE_H, dom.height - y)
    const file = `tile-${tiles.length + 1}.png`
    await page.screenshot({ path: path.join(ws, file), clip: { ...clip, y, height: h }, fullPage: true })
    tiles.push({ file, y, h })
    if (y + h >= dom.height) break
  }
  fs.writeFileSync(path.join(ws, "tiles.json"), JSON.stringify(tiles))
  const half = await browser.newPage({ viewport: VIEWPORT, deviceScaleFactor: 0.5 })
  await half.goto(url)
  await half.waitForFunction(() => window.__READY__ === true, null, { timeout: 30000 })
  await half.screenshot({ path: path.join(ws, "thumb.png"), clip, fullPage: true })
} finally {
  await browser.close()
  server.close()
}
finish()

function finish() {
  fs.writeFileSync(path.join(ws, "checks.json"), JSON.stringify(findings, null, 1))
  const shots = fs.existsSync(path.join(ws, "tiles.json")) ? JSON.parse(fs.readFileSync(path.join(ws, "tiles.json"), "utf8")).map((t) => t.file) : []
  console.log(findings.length ? `程序检查发现 ${findings.length} 个问题:` : "程序检查全部通过。")
  for (const f of findings) console.log(`- [${f.check}]${f.line ? ` Page.tsx 第 ${f.line} 行:` : " "}${f.msg}`)
  if (shots.length) console.log(`截图:thumb.png(整页缩略),${shots.join("、")}(从上到下的切块)`)
}

// Report components: the page frame and the content pieces a report is built from.
// Content components draw with render.tsx (the same code the eval-set pages were
// rendered with); the frame components take JSX children.
//
// Frame (swiss): 12 columns of 74px with 24px gutters, 1152px wide. Section titles
// hang in the left 3 columns; section content sits in the right 9.
import * as React from "react"

import { cn } from "@/lib/utils"
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area"
import { Separator } from "@/components/ui/separator"
import { Node, type SpecNode } from "./render"

const SPAN = ["", "col-span-1", "col-span-2", "col-span-3", "col-span-4", "col-span-5", "col-span-6", "col-span-7", "col-span-8", "col-span-9", "col-span-10", "col-span-11", "col-span-12"]
const COLS: Record<number, string> = { 2: "grid-cols-2", 3: "grid-cols-3", 4: "grid-cols-4", 6: "grid-cols-6", 9: "grid-cols-9", 12: "grid-cols-12" }

type Placed = { span?: number; className?: string }

export function Page({ title, meta = [], className, children }: { title: string; meta?: string[]; className?: string; children: React.ReactNode }) {
  return (
    <main data-slot="page" className={cn("mx-auto flex w-full max-w-6xl flex-col gap-[192px] py-[72px]", className)}>
      <header data-slot="page-header" className="grid h-36 grid-cols-12 content-start items-baseline-last gap-x-6">
        <div className="col-span-3 flex flex-col text-sm leading-6 text-muted-foreground">
          {meta.map((m, i) => <span key={i}>{m}</span>)}
        </div>
        <h1 className="col-span-9 text-5xl leading-[48px] font-medium">{title}</h1>
      </header>
      {children}
    </main>
  )
}

export function Section({ title, description, className, children }: { title: string; description?: string; className?: string; children: React.ReactNode }) {
  return (
    <section data-slot="section" className="grid grid-cols-12 items-start gap-x-6">
      <div data-slot="section-header" className="col-span-3 flex flex-col">
        <h2 className="text-xl leading-6 font-medium">{title}</h2>
        {description && <p className="text-sm leading-6 text-muted-foreground">{description}</p>}
      </div>
      <div data-slot="section-body" className={cn("col-span-9 flex flex-col gap-[192px]", className)}>{children}</div>
    </section>
  )
}

// A group of content, 8px from the title to its content and 24px between the
// content pieces. The group's title is a sub-head: it is set at body size and
// bold, one size step below the section title (14px against the section's
// 20px), so a run of groups reads as separate blocks under their section
// instead of repeating the section heading at its own size.
export function Group({ title, className, children }: { title?: string; className?: string; children: React.ReactNode }) {
  return (
    <div data-slot="group" className="flex flex-col gap-2">
      {title && <h3 data-slot="group-title" className="text-sm leading-6 font-semibold">{title}</h3>}
      <div data-slot="group-body" className={cn("flex flex-col gap-6", className)}>{children}</div>
    </div>
  )
}

// Rows are 144px fields unless fields={false}; a child takes `span` columns (and a Block `rows` fields).
export function Grid({ cols = 9, fields = true, className, children, span }: Placed & { cols?: number; fields?: boolean; children: React.ReactNode }) {
  return (
    <div data-slot="grid" className={cn("grid gap-x-6 gap-y-6", COLS[cols], span && SPAN[span], className)} style={fields ? { gridAutoRows: "144px" } : undefined}>
      {children}
    </div>
  )
}

export function Block({ span, rows, title, description, className, contentClassName, children }: Placed & { rows?: number; title?: string; description?: string; contentClassName?: string; children: React.ReactNode }) {
  return (
    <div data-slot="block" className={cn("flex min-h-0 flex-col", span && SPAN[span], className)} style={rows ? { gridRow: `span ${rows}` } : undefined}>
      {(title || description) && (
        <div data-slot="block-header" className="flex flex-col">
          {title && <h3 className="text-sm leading-6 font-semibold">{title}</h3>}
          {description && <p className="text-sm leading-6 text-muted-foreground">{description}</p>}
        </div>
      )}
      <div data-slot="block-content" className={cn("flex flex-1 flex-col gap-3", contentClassName)}>{children}</div>
    </div>
  )
}

// Content components: props are the fields documented in components.md.
const content = (type: string) =>
  function Content(props: Placed & Record<string, unknown>) {
    return <Node node={{ type, ...props } as SpecNode} ctx={{ span: props.span }} />
  }

export const Stat = content("stat")
export const DataTable = content("table")
export const TrendChart = content("line-chart")
export const BarChart = content("bar-chart")
export const ProgressList = content("progress-list")
export const List = content("list")
export const KV = content("kv")

export function Text({ children, className, span }: Placed & { children: string }) {
  return <Node node={{ type: "text", text: children, className }} ctx={{ span }} />
}

// Screenshots: one screen per Figure, laid out in a FigureStrip that scrolls
// sideways on a shadcn ScrollArea. The strip is what pins the row height: every
// image is drawn at that one height and keeps its own width, so phone
// screenshots and wider analysis screenshots line up in one row without being
// cropped; anything past the right edge is clipped and reached with the
// scrollbar. The scrollbar only appears while the strip is hovered: an
// always-visible bar reads as a rule under the row of screens, which is not a
// line the design gives.
export function FigureStrip({ className, children, ...props }: React.ComponentProps<typeof ScrollArea>) {
  return (
    <ScrollArea data-slot="figure-strip" type="hover" className={cn("w-full min-w-0", className)} {...props}>
      <div
        data-slot="figure-strip-row"
        className={cn(
          "flex w-max gap-12 pb-4",
          "[&_[data-slot=figure-image]]:h-96 [&_[data-slot=figure-image]]:w-auto",
        )}
      >
        {children}
      </div>
      <ScrollBar orientation="horizontal" />
    </ScrollArea>
  )
}

// The screenshots in a comparison set (one interface plus its colour-vision
// simulations) are read side by side, so they take the content width two to a
// row instead of being shrunk to one strip height. Each image fills its cell and
// keeps its ratio, which keeps the text inside the screenshots legible.
export function FigureGrid({ className, children, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="figure-grid"
      className={cn(
        "grid w-full grid-cols-2 gap-x-6 gap-y-6",
        "[&>[data-slot=figure]]:w-full [&>[data-slot=figure]]:min-w-0",
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
}

// The comparison set for colour vision (the interface plus its simulations) has
// to be read as one group: all four views together, at a size where what is
// inside them still reads, and the whole group inside one screen. Two columns
// give the width (a quarter of the content column would be a thumbnail); the
// images keep their own ratio and are capped at one height, so the group is
// always two bounded rows whatever the screenshots' proportions are, and a tall
// screenshot is not stretched into a second screen. The caption runs the width
// of its cell, so a narrow view does not wrap its label into a column of lines.
export function FigureCompare({ className, children, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="figure-compare"
      className={cn(
        "grid w-full grid-cols-2 gap-x-6 gap-y-6",
        "[&>[data-slot=figure]]:w-full [&>[data-slot=figure]]:min-w-0",
        "[&_[data-slot=figure-image]]:max-h-64 [&_[data-slot=figure-image]]:w-auto [&_[data-slot=figure-image]]:max-w-full",
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
}

// A group marker: one hairline, the same 1px weight as a table's row lines, with
// an optional label on the line above it. Used where the page groups blocks of
// content (one product per chain-detail group) and the only other rule in sight
// is the table's, so the two read as the same line.
export function Rule({ label, className, ...props }: React.ComponentProps<"div"> & { label?: string }) {
  return (
    <div data-slot="rule" className={cn("flex flex-col gap-2", className)} {...props}>
      {label && <span className="text-xs leading-6 text-muted-foreground">{label}</span>}
      <Separator />
    </div>
  )
}

// As wide as its image: the label and text wrap under it instead of widening (and stretching) the image.
export function Figure({ className, ...props }: React.ComponentProps<"figure">) {
  return <figure data-slot="figure" className={cn("flex w-min shrink-0 flex-col gap-2", className)} {...props} />
}

// The image takes the width its cell gives it and keeps its own ratio: nothing
// is cropped and no height is fixed here. A strip pins the row height (all its
// images share one height, widths differ); a comparison grid lets the column
// width decide, so a view read for its detail is never squeezed down to a strip
// thumbnail.
export function FigureImage({ className, ...props }: React.ComponentProps<"img">) {
  return <img data-slot="figure-image" className={cn("block w-full max-w-none", className)} {...props} />
}

// The screen or view name, on the line the design gives 12px notes.
export function FigureLabel({ className, ...props }: React.ComponentProps<"figcaption">) {
  return <figcaption data-slot="figure-label" className={cn("text-xs leading-6 text-muted-foreground", className)} {...props} />
}

// What happens on the screen (content, action, fields), in body type.
export function FigureText({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="figure-text" className={cn("text-sm leading-6", className)} {...props} />
}

